// ============================================
// N8N CART DEBOUNCE INTEGRATION
// ============================================

// Delay time — yahan change karo, code mein kahi aur nahi
define( 'N8N_CART_DEBOUNCE_SECONDS', 10 );

// n8n webhook URL — yahan change karo
define( 'N8N_WEBHOOK_URL', 'https://motion-estranged-cranium.ngrok-free.dev/webhook-test/c31d2ae4-cc6a-4285-a9ef-cfd7f8d36a5f' );


// Jab bhi product cart mein add ho, time record karo aur delayed check schedule karo
add_action( 'woocommerce_add_to_cart', 'debounce_cart_add', 10, 6 );

function debounce_cart_add( $cart_item_key, $product_id, $quantity, $variation_id, $variation, $cart_item_data ) {

    // Session ke hisaab se unique key — logged-in user ki user_id,
    // guest ki random hash. Alag users ka cart mix nahi hoga.
    $session_key   = WC()->session ? WC()->session->get_customer_id() : 'guest';
    $transient_key = 'n8n_last_add_' . $session_key;

    // WHY: Ye transient sirf "last add ka time" record karta hai.
    // Har naye add pe overwrite hota hai — isse pata chalta hai
    // ke pichla add "final" tha ya uske baad koi aur add hua (reset).
    set_transient( $transient_key, time(), N8N_CART_DEBOUNCE_SECONDS + 45 );

    // WHY Action Scheduler: wp_schedule_single_event WP-Cron pe depend karta
    // hai jo unreliable hai. Action Scheduler (WooCommerce ke saath aata
    // hai) proper background queue chalata hai.
    as_schedule_single_action(
        time() + N8N_CART_DEBOUNCE_SECONDS,
        'n8n_check_and_send_cart',
        array( 'session_key' => $session_key ),
        'n8n-cart-sync'
    );
}


// 15 sec baad ye chalega — check karega reset hua ya nahi
add_action( 'n8n_check_and_send_cart', 'n8n_check_and_send_cart_callback' );

function n8n_check_and_send_cart_callback( $session_key ) {

    $transient_key = 'n8n_last_add_' . $session_key;
    $last_add_time = get_transient( $transient_key );

    // WHY: Agar transient nahi mili, matlab pehle hi kisi run ne
    // cart bhej diya tha aur clean kar diya — dobara mat bhejo.
    if ( false === $last_add_time ) {
        return;
    }

    // WHY: Agar last add ke baad 15 sec se kam guzre, matlab beech mein
    // naya product add ho chuka — ye purani run chup ho jaye.
    if ( ( time() - $last_add_time ) < N8N_CART_DEBOUNCE_SECONDS ) {
        return;
    }

    // Cart khali hai to bhejne ki zarurat nahi
    if ( ! WC()->cart || WC()->cart->is_empty() ) {
        delete_transient( $transient_key );
        return;
    }

    // Poori cart list assemble karo
    $items = array();
    foreach ( WC()->cart->get_cart() as $item ) {
        $product = $item['data'];
        $items[] = array(
            'product_id'   => $item['product_id'],
            'product_name' => $product ? $product->get_name() : '',
            'price'        => $product ? $product->get_price() : 0,
            'quantity'     => $item['quantity'],
        );
    }

    $user = wp_get_current_user();

    $body = array(
        'event_type' => 'cart_finalized',
        'session_id' => $session_key,   // <-- yahan add ki hai
        'items'      => $items,
        'user_email' => $user->exists() ? $user->user_email : 'Guest User',
        'sent_at'    => current_time( 'mysql' ),
    );

    wp_remote_post( N8N_WEBHOOK_URL, array(
        'method'      => 'POST',
        'headers'     => array( 'Content-Type' => 'application/json; charset=utf-8' ),
        'body'        => wp_json_encode( $body ),
        'data_format' => 'body',
    ) );

    // WHY: Send hone ke baad transient clean karo — agla cycle confuse na ho.
    delete_transient( $transient_key );
}
